steps.content:
mkdir -p /var/www/html
echo 'Welcome to the benchmark webserver' > /var/www/html/index.html
echo 'Page not found - Please check your URL' > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default
if ! grep -Fq 'log_format benchmark' /etc/nginx/nginx.conf; then
  sed -i "/http {/a\\    log_format benchmark '\$time_local \$request_method \$status \"\$http_user_agent\"';" /etc/nginx/nginx.conf
fi
if ! grep -Fq 'zone=benchmark_limit:10m' /etc/nginx/nginx.conf; then
  sed -i "/http {/a\\    limit_req_zone \$binary_remote_addr zone=benchmark_limit:10m rate=10r/s;" /etc/nginx/nginx.conf
fi
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
}
EOF
